function planVisitDates(){
  const sameDay=$('p4PlanMode').value==='same-day';
  const startDate=$('p4PlanStart').value,endDate=sameDay?startDate:$('p4PlanEnd').value;
  if(!startDate||!endDate)throw Error('Enter the visit dates first.');
  if(endDate<startDate)throw Error('End date cannot be before start date.');
  return{startDate,endDate};
}
function rebuildPlanRows(){
  const p=bookingPlan;
  if(!p)return;
  p.rows=[];
  for(const dog of p.dogs)for(const visit of p.visits){
    p.rows.push({key:`${dog.key}:${visit.startDate}:${visit.endDate}`,dogKey:dog.key,payload:{...visit},status:'pending'});
  }
  invalidatePlanReview();
}
function addPlanVisit(){
  if(singleSaveInProgress)throw Error('Wait for the current booking save to finish.');
  const p=ensurePlan(),visit=planVisitDates();
  if(planStarted())return;
  if(p.visits.some(item=>item.startDate===visit.startDate&&item.endDate===visit.endDate))throw Error('Those dates are already in the plan.');
  p.visits.push(visit);
  clearPlanDraftMessage();
  rebuildPlanRows();
  renderPlan();
}
function addWeeklyPlanVisits(){
  if(singleSaveInProgress)throw Error('Wait for the current booking save to finish.');
  const p=ensurePlan();
  if(planStarted())return;
  const start=$('p4PlanStart').value,until=$('p4PlanUntil').value;
  if(!start||!until)throw Error('Choose a start date and weekly end date.');
  const visits=planEngine().weeklyVisits(start,until);
  if(!Array.isArray(visits)||!visits.length)throw Error('No weekly visit dates fall within that range.');
  p.visits.push(...visits.filter(visit=>!p.visits.some(item=>item.startDate===visit.startDate&&item.endDate===visit.endDate)));
  clearPlanDraftMessage();
  rebuildPlanRows();
  renderPlan();
}
function planDateLabel(value){
  const [year,month,day]=String(value||'').split('-').map(Number);
  if(!year||!month||!day)return String(value||'');
  return new Intl.DateTimeFormat('en-AU',{weekday:'short',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,month-1,day)));
}
function planVisitLabel(visit){
  const sameDay=visit.startDate===visit.endDate;
  return sameDay?`Same-day visit · ${planDateLabel(visit.startDate)}`:`Overnight stay · ${planDateLabel(visit.startDate)} – ${planDateLabel(visit.endDate)}`;
}
